import { readFile, writeFile, mkdir } from "node:fs/promises";
import { existsSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, "..");
const DOCS = path.join(ROOT, "docs-site");

const MARK =
  "<!-- AUTO-GENERATED by scripts/sync-agents-docs.mjs — do not edit; правь docs-site/ -->";

const GENERATED_CONTEXT_BUDGETS = {
  "AGENTS.md": { maxLines: 220, maxBytes: 32_000 },
  "CLAUDE.md": { maxLines: 220, maxBytes: 32_000 },
  "incubator/mobile/delphi/AGENTS.md": { maxLines: 180, maxBytes: 24_000 },
  "core/ark/crates/ark-core/AGENTS.md": { maxLines: 180, maxBytes: 24_000 },
};

// ─────────────────────────────────────────────────────────────────────────────
// utils
// ─────────────────────────────────────────────────────────────────────────────

async function readDoc(rel) {
  const p = path.join(DOCS, rel);
  if (!existsSync(p)) {
    console.warn(`[skip] нет файла: ${rel}`);
    return "";
  }
  return await readFile(p, "utf8");
}

function stripFrontmatter(md) {
  if (!md.startsWith("---")) return md;
  const end = md.indexOf("\n---", 3);
  if (end === -1) return md;
  return md.slice(end + 4).replace(/^\s*\n/, "");
}

function rewriteLinks(md, _siteOrigin = "/") {
  // Превращаем относительные ссылки на страницы сайта в указание пути.
  // `/concepts/architecture` → `docs-site/concepts/architecture.md`
  return md.replace(/\]\((\/[a-z0-9\-/]+)\)/gi, (_, p) => {
    if (p.startsWith("//") || p.startsWith("http")) return `](${p})`;
    // Не трогаем якоря и явные .md
    if (p.endsWith(".md")) return `](docs-site${p})`;
    const segs = p.split("#");
    const route = segs[0].replace(/\/$/, "");
    const hash = segs[1] ? `#${segs[1]}` : "";
    return `](docs-site${route}.md${hash})`;
  });
}

async function write(rel, content) {
  assertGeneratedContextBudget(rel, content);
  const full = path.join(ROOT, rel);
  await mkdir(path.dirname(full), { recursive: true });
  await writeFile(full, content, "utf8");
  console.log(`  ✓ ${rel}`);
}

function assertGeneratedContextBudget(rel, content) {
  const budget = GENERATED_CONTEXT_BUDGETS[rel];
  if (!budget) return;

  const lineCount = content.split(/\r?\n/).length;
  const byteCount = Buffer.byteLength(content, "utf8");
  if (lineCount <= budget.maxLines && byteCount <= budget.maxBytes) return;

  throw new Error(
    `${rel} exceeds context budget: ${lineCount}/${budget.maxLines} lines, ${byteCount}/${budget.maxBytes} bytes. ` +
      "Move detail into docs-site/ and keep the generated root context as pointers.",
  );
}

// ─────────────────────────────────────────────────────────────────────────────
// шаблоны
// ─────────────────────────────────────────────────────────────────────────────

function header(title, extraLines = []) {
  return [
    `# ${title}`,
    "",
    MARK,
    "",
    "Источник правды — `docs-site/`. Этот файл собирается автоматически из",
    "соответствующих страниц документации скриптом `scripts/sync-agents-docs.mjs`.",
    "Открой собранный сайт (`bun run docs:dev`, http://localhost:5173/) для",
    "удобного чтения.",
    ...extraLines,
    "",
    "---",
    "",
  ].join("\n");
}

// ─────────────────────────────────────────────────────────────────────────────
// корневой AGENTS.md / CLAUDE.md
// ─────────────────────────────────────────────────────────────────────────────

async function buildRootAgents() {
  const agentCore = await readDoc("agents/claude-md-core.md");

  const agentsBody =
    header("AGENTS.md — Kosmos", [
      "",
      "Этот файл намеренно компактный: он грузится в агентский контекст по умолчанию.",
      "Детальные правила живут в `docs-site/` и подгружаются по ссылкам только когда задача касается области.",
      "Полный inline-reference для редких случаев — `docs-site/public/full-llms.txt`.",
    ]) +
    "\n" +
    rewriteLinks(stripFrontmatter(agentCore)).trim() +
    "\n";

  await write("AGENTS.md", agentsBody);

  // CLAUDE.md — slim version. Anthropic best-practices: < 200 строк, иначе
  // Claude начинает игнорировать правила (https://code.claude.com/docs/en/best-practices).
  // CLAUDE.md загружается каждую сессию каждый turn. Source — единственный
  // curated файл `agents/claude-md-core.md`; per-app forbidden и situational
  // знания живут в `docs-site/` и подгружаются Claude'ом по необходимости.
  // Full detail stays in docs-site/ and full-llms.txt; the generated root files
  // are boot context, not an inline encyclopedia.
  const claudeCore = await readDoc("agents/claude-md-core.md");

  const claudeHeader = [
    "# CLAUDE.md",
    "",
    MARK,
    "",
    "Контекст работы над монорепо Kosmos для Claude Code.",
    "Источник — `docs-site/agents/claude-md-core.md`. Регенерация — `bun run docs:sync`.",
    "",
    "Компактный cross-agent контекст — `AGENTS.md` в корне. Глубокие правила — страницы под `docs-site/`.",
    "",
    "---",
    "",
  ].join("\n");

  await write(
    "CLAUDE.md",
    claudeHeader + "\n" + rewriteLinks(stripFrontmatter(claudeCore)).trim() + "\n",
  );
}

// ─────────────────────────────────────────────────────────────────────────────
// per-app / per-package / per-service AGENTS.md
// ─────────────────────────────────────────────────────────────────────────────

export {
  ROOT,
  DOCS,
  MARK,
  readDoc,
  stripFrontmatter,
  rewriteLinks,
  write,
  assertGeneratedContextBudget,
  header,
};
